{"files":{"tokenizer.js":"function tokenize(text) {
  var normalized = normalize(text);
  var tokens = [];
  var current = '';
  var i, ch, code;
  for (i = 0; i < normalized.length; i++) {
    ch = normalized[i];
    code = normalized.charCodeAt(i);
    if ((code >= 48 && code <= 57) || (code >= 65 && code <= 90) || (code >= 97 && code <= 122)) {
      current += ch;
    } else if (ch === "'") {
      if (current.length > 0) {
        current += ch;
      }
    } else {
      if (current.length > 0) {
        if (current !== 'a' && current !== 'the') {
          tokens.push(current);
        }
        current = '';
      }
    }
  }
  if (current.length > 0) {
    if (current !== 'a' && current !== 'the') {
      tokens.push(current);
    }
  }
  return tokens;
}

function normalize(text) {
  var s = String(text);
  s = s.normalize('NFKC');
  s = s.normalize('NFD');
  var result = '';
  var i, code;
  for (i = 0; i < s.length; i++) {
    code = s.charCodeAt(i);
    if (code >= 0x0300 && code <= 0x036F) {
      continue;
    }
    result += s[i];
  }
  result = result.toLowerCase();
  result = result.replace(/\s+/g, ' ');
  result = result.trim();
  return result;
}

function analyze(text) {
  var tokens = tokenize(text);
  var count = tokens.length;
  var unique = [];
  var frequencies = {};
  var seen = {};
  var i, token;
  for (i = 0; i < tokens.length; i++) {
    token = tokens[i];
    if (frequencies[token] === undefined) {
      frequencies[token] = 0;
    }
    frequencies[token] += 1;
    if (!seen[token]) {
      seen[token] = true;
      unique.push(token);
    }
  }
  var summary = count + ' tokens; ' + unique.length + ' unique';
  return { tokens: tokens, count: count, unique: unique, frequencies: frequencies, summary: summary };
}
"},"message":"Implemented tokenize, normalize, and analyze per spec. normalize: NFKC, NFD, strip U+0300-U+036F, lowercase, collapse spaces, trim. tokenize: ASCII alphanumeric runs with interior apostrophes, removes 'a'/'the' after normalization, accented letters act as separators. analyze returns exact object. Please review edge cases like empty string and constructor property. Ready for peer feedback."}
